import {
  endInteractionSpan,
  runWithInteractionContext,
} from 'src/utils/telemetry/sessionTracing.js'
import { extractTextContent } from 'src/utils/messages.js'

// Shared lazy MCP context for hooks without an explicit per-call client list.
let mcpClientsForHooksGetter:
  | (() => readonly import('../services/mcp/types.js').MCPServerConnection[])
  | undefined

export function setMcpClientsForHooksGetter(
  getter: typeof mcpClientsForHooksGetter,
): void {
  mcpClientsForHooksGetter = getter
}

export function getMcpClientsForHooks():
  | readonly import('../services/mcp/types.js').MCPServerConnection[]
  | undefined {
  return mcpClientsForHooksGetter?.()
}

